import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { brandColors } from "./theme.config.ts";
import { generatePalettes, generateSemanticTokens, shadeOrder } from "./theme.ts";

const palettes = generatePalettes(brandColors);
const semantic = generateSemanticTokens(palettes);
const lines = [
  "/* Generated by @fs/design-system. Do not edit. */",
  "@custom-variant dark (&:is(.dark *));",
  ":root {",
  ...Object.entries(palettes).flatMap(([name, palette]) => shadeOrder.map((shade) => `  --color-${name}-${shade}: ${palette[shade]};`)),
  ...Object.entries(semantic.light).map(([name, value]) => `  --${name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)}: ${value};`),
  "  --destructive: #B42318;",
  "  --destructive-foreground: #FFFFFF;",
  "  --success: #176B4D;",
  "  --warning: #8A4B08;",
  "  --info: #1D4ED8;",
  "  --radius: 0.625rem;",
  "}",
  ".dark {",
  ...Object.entries(semantic.dark).map(([name, value]) => `  --${name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)}: ${value};`),
  "  --destructive: #F97066;",
  "  --destructive-foreground: #211B18;",
  "  --success: #5ED6A0;",
  "  --warning: #F4B740;",
  "  --info: #93B4FF;",
  "}",
  "@theme inline {",
  ...["background", "foreground", "card", "card-foreground", "popover", "popover-foreground", "primary", "primary-foreground", "secondary", "secondary-foreground", "tertiary", "tertiary-foreground", "accent", "accent-foreground", "muted", "muted-foreground", "border", "input", "ring", "hover", "active", "selected", "disabled", "destructive", "destructive-foreground", "success", "warning", "info"].map((name) => `  --color-${name}: var(--${name});`),
  ...Object.entries(palettes).flatMap(([name]) => shadeOrder.map((shade) => `  --color-${name}-${shade}: var(--color-${name}-${shade});`)),
  "  --radius-sm: calc(var(--radius) - 4px);",
  "  --radius-md: calc(var(--radius) - 2px);",
  "  --radius-lg: var(--radius);",
  "  --radius-xl: calc(var(--radius) + 4px);",
  "  --shadow-sm: 0 1px 2px rgb(33 27 24 / 8%);",
  "  --shadow-card: 0 4px 12px rgb(33 27 24 / 8%);",
  "  --shadow-elevated: 0 12px 32px rgb(33 27 24 / 12%);",
  "  --font-display: var(--font-display-family);",
  "  --font-body: var(--font-body-family);",
  "  --font-sans: var(--font-body-family);",
  "  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;",
  "}",
  "",
].join("\n");

const output = resolve(import.meta.dirname, "../generated/tokens.css");
await mkdir(dirname(output), { recursive: true });
await writeFile(output, lines);
console.log(`Generated ${output}`);
